const demoSugars=new Set(['glucose','fructose','maltose','lactose','sucrose']);
let demoTimer=null,demoLast=0;
function registerDemoReagents(){for(const r of [['Vinegar (ethanoic acid model)','CH₃COOH · 0.83 M','acid','Colour & foam','#f7faf8','colourless'],['Dishwashing liquid (neutral model)','Neutral surfactant mixture','detergent','Colour & foam','#f7faf8','colourless'],['Red food colouring','Food dye · visual trace','foodDye','Colour & foam','#d54351','red']])if(!reagents.some(x=>x[0]===r[0]))reagents.push(r);}
function demoResult(product,equation,note,color,extra={}){return {product,equation,note,color,solutionColor:color,precipitate:false,gas:null,status:'qualitative',foodTest:true,...extra};}
function demoPredict(items,conditions={}){
 const e=benchEntries(items),has=t=>e.some(x=>x.type===t),p=Math.max(0,Math.min(1,Number(conditions.demoProgress??1))),V=e.reduce((s,x)=>s+x.volume/1000,0);
 const unknown=note=>demoResult('Demonstration outside modeled conditions','No unique overall equation assigned.',note,'#ede5ef',{status:'unsupported'});
 if(has('permanganate')&&e.some(x=>demoSugars.has(x.type))){
  if(e.some(x=>!['water','permanganate','carbonate','base',...demoSugars].includes(x.type)))return unknown('Competing reagents are present. Use a fresh sugar, permanganate and sodium carbonate or sodium hydroxide mixture.');
  if(e.some(x=>x.type!=='water'&&(!Number.isFinite(x.n)||x.c<0||x.c>1)))return unknown('Use measured dilute solutions between 0 and 1 mol/L for this demonstration.');
  const mn=e.filter(x=>x.type==='permanganate').reduce((s,x)=>s+x.n,0),sugar=e.filter(x=>demoSugars.has(x.type)).reduce((s,x)=>s+x.n,0),alk=e.filter(x=>['base','carbonate'].includes(x.type));
  if(!mn||!sugar)return demoResult('No sugar–permanganate conversion assigned','','A reactant has zero concentration.','#f7faf8');
  if(alk.some(x=>!['NaOH','Na2CO3'].includes(x.f)))return unknown('This reference model uses sodium hydroxide or sodium carbonate as the alkaline medium.');
  const ph=foodCabbagePH(e.map(x=>['base','carbonate','water'].includes(x.type)?x:{...x,type:'water',f:'H2O',n:0}));
  if(!Number.isFinite(ph)||ph<10)return unknown('The alkaline chameleon pathway requires sufficient alkalinity. Acidic and near-neutral sugar oxidation are outside this demonstration.');
  if(sugar<10*mn)return unknown('This colour-stage model requires a large sugar excess (at least 10 mol sugar per mol permanganate). It does not predict a unique endpoint for oxidant-rich mixtures or all organic oxidation products.');
  const strong=alk.some(x=>x.f==='NaOH'&&x.n>0)&&ph>=12,stages=strong?[[0,'#79298e','Purple permanganate'],[.24,'#426093','Blue: purple and green species coexist'],[.48,'#398a58','Green manganate'],[.74,'#c2a947','Yellow / orange colloidal MnO₂'],[1,'#98703e','Brown manganese dioxide']]:[[0,'#79298e','Purple permanganate'],[.42,'#8b5272','Purple fading; brown MnO₂ forming'],[1,'#98703e','Brown manganese dioxide']];
  let lo=stages[0],hi=stages.at(-1);for(let i=1;i<stages.length;i++)if(p<=stages[i][0]){lo=stages[i-1];hi=stages[i];break;}const t=(p-lo[0])/(hi[0]-lo[0]),color=benchTint([[lo[1],1-t],[hi[1],t]]),stage=p===1?stages.at(-1)[2]:lo[2];
  const duration=(strong?18:30)*(e.some(x=>x.type==='sucrose')?1.6:1)*Math.max(.65,Math.min(1.8,.02/(sugar/V)));
  return demoResult('Alkaline sugar oxidation · manganese colour sequence','MnO₄⁻ + e⁻ → MnO₄²⁻; MnO₄²⁻ + 2e⁻ + 2H₂O → MnO₂(s) + 4OH⁻',`${stage}. ${strong?'Strong alkali permits an observable green manganate stage; blue is a mixture of purple and green.':'In the milder carbonate medium the reference observation is purple → brown; a persistent green stage is not assumed.'} Sugar is oxidised to a mixture of products; no unique organic product or yield is assigned. ${mn/V>.001?'The concentrated purple colour can mask intermediate shades. ':''}Animation time and RGB shades are illustrative, not calibrated kinetics or absorbance.`,color,{demoKind:'chameleon',demoStage:stage,demoDuration:duration,precipitate:p>.55,precipitateColor:'#825333',foodInference:'Colour changes indicate manganese reduction. Carbonate supplies alkalinity (CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻). Sucrose can react here despite being negative in the untreated Benedict test; the reagents and conditions differ.'});
 }
 if(has('bicarbonate')&&has('acid')&&(has('detergent')||has('foodDye')||e.some(x=>x.f==='CH3COOH'))){
  if(e.some(x=>!['water','acid','bicarbonate','detergent','foodDye'].includes(x.type))||e.some(x=>x.type==='acid'&&x.f!=='CH3COOH'))return unknown('Use only vinegar / ethanoic acid, sodium bicarbonate, water, neutral detergent and optional food dye for this foam model.');
  const reactants=e.filter(x=>['acid','bicarbonate'].includes(x.type));if(reactants.some(x=>!Number.isFinite(x.n)||x.c<0||x.c>1||x.type==='bicarbonate'&&x.f!=='NaHCO3'))return unknown('Use aqueous ethanoic acid and sodium bicarbonate stocks with known concentrations from 0 to 1 M.');
  const acid=reactants.filter(x=>x.type==='acid').reduce((s,x)=>s+x.n,0),base=reactants.filter(x=>x.type==='bicarbonate').reduce((s,x)=>s+x.n,0),gas=Math.min(acid,base),litres=gas*.082057*298.15,soap=has('detergent'),dye=has('foodDye'),color=dye?'#dc6370':'#edf3ee';
  return demoResult(gas>0?'Sodium ethanoate solution + carbon dioxide':'No CO₂ production assigned','CH₃COOH + NaHCO₃ → CH₃COONa(aq) + CO₂(g) + H₂O',`Theoretical total CO₂: ${gas.toExponential(3)} mol (about ${(litres*1000).toFixed(1)} mL of ideal dry gas at 25 °C and 1 atm). ${acid<base?'Vinegar acid':base<acid?'Bicarbonate':'Both reactants'} limits the stoichiometric yield. ${soap?'Detergent traps gas as foam.':'Without detergent, bubbles escape and no lasting foam column is shown.'} CO₂ is colourless; ${dye?'the added dye colours the liquid and foam.':'foam looks white because bubbles scatter light.'} Foam geometry and overflow are illustrative; dissolved CO₂, flow and liquid loss are not calculated.`,color,{demoKind:'volcano',demoStage:gas<=0?'No gas: a reactant is absent':p<1?'CO₂ bubbling / foam rising':'Gas production finished; foam settling',demoDuration:16,gas:gas>0&&p<1?'carbonDioxide':null,demoGasMoles:gas,demoGasML:litres*1000,demoFoam:soap&&gas>0,demoDye:dye,foodInference:'This is an acid–bicarbonate reaction. The volcano cone is a prop; no lava, rock, flame or coloured gas is formed.'});
 }
 return null;
}
function demoSignature(a){return JSON.stringify(a.contents.map(x=>[x.reagent,x.formula,x.molarity,x.volume,x.mass]));}
function demoSync(){for(const a of apparatus){const out=a.mixed?demoPredict(a.contents,a):null;if(!out?.demoKind){a.demoActive=false;continue;}const sig=demoSignature(a);if(a.demoSignature!==sig){a.demoSignature=sig;a.demoProgress=0;a.demoActive=true;}}if(apparatus.some(a=>a.demoActive)&&!demoTimer){demoLast=Date.now();demoTimer=setInterval(demoTick,180);}}
function demoEffect(a){const out=a.mixed?demoPredict(a.contents,a):null;if(!out?.demoKind)return '';const p=a.demoProgress??1,foam=out.demoFoam&&p>0,capacity=equipment.find(x=>x[0]===a.type)?.[3]||100,expansion=Math.min(1,Math.sqrt(out.demoGasML/Math.max(20,capacity-(a.volume||0)))),amp=foam?Math.sin(Math.PI*p)**.5*expansion:0;return `<div class="demo-effect" data-demo-effect="${a.id}" style="left:calc(${a.x}% + 38px);top:calc(${a.y}% + 30px);--foam:${out.demoDye?'#f9b3b8':'#fff5dd'};--rise:${Math.round(amp*160)}px;--spread:${Math.round(amp*75)}px"><span class="demo-stage">${out.demoKind==='volcano'?'CO₂ · '+(foam?'foam':'bubbles'):out.demoStage}</span>${out.demoKind==='volcano'?`<span class="demo-cone"></span><small class="demo-prop">volcano prop</small>${foam?'<span class="demo-foam"></span><span class="demo-overflow"></span>':''}`:''}</div>`;}
function demoEffects(){return apparatus.map(demoEffect).join('');}
function demoTick(){const now=Date.now(),dt=Math.min(1,(now-demoLast)/1000);demoLast=now;for(const a of apparatus){if(!a.demoActive)continue;const out=demoPredict(a.contents,a);if(!a.mixed||!out?.demoKind||a.demoSignature!==demoSignature(a)){a.demoActive=false;continue;}a.demoProgress=Math.min(1,(a.demoProgress||0)+dt/out.demoDuration);if(a.demoProgress>=1)a.demoActive=false;const stage=demoPredict(a.contents,a),node=document.querySelector(`[data-app="${a.id}"]`),d=equipment.find(x=>x[0]===a.type);if(node&&d){node.querySelector('.equip-icon').innerHTML=equipSvg(a.type,a.volume,d[3],stage.color,a.id,null,stage.precipitate?stage.precipitateColor:null);const fill=node.querySelector('.fillmark');if(fill)fill.style.background=stage.color;}document.querySelector(`[data-demo-effect="${a.id}"]`)?.remove();document.querySelector('#benchCanvas')?.insertAdjacentHTML('beforeend',demoEffect(a));}demoRefreshStatus();if(document.querySelector('[data-bench-panel="results"]')?.hidden===false)benchRefreshResults();if(!apparatus.some(a=>a.demoActive)){clearInterval(demoTimer);demoTimer=null;}}
function demoPanel(){return `<p>Prepare a reference mixture, then mix it on the bench. You can also add the same reagents manually with your own concentrations and volumes.</p><label for="demoPreset">Demonstration</label><select id="demoPreset"><option value="carbonate">Glucose + KMnO₄ + sodium carbonate</option><option value="sucrose">Sucrose + KMnO₄ + sodium carbonate (slower)</option><option value="hydroxide">Glucose + KMnO₄ + NaOH · chameleon</option><option value="volcano">Vinegar + bicarbonate + detergent · volcano</option></select><div class="row" style="margin:12px 0"><button class="btn" data-demo="prepare">Prepare new vessel</button><button class="btn soft" data-demo="mix">Mix & animate</button><button class="btn secondary" data-demo="pause">Pause / resume</button><button class="btn secondary" data-demo="replay">Replay observation</button></div><div id="demoStatus" role="status"></div><p class="notice">Animation speed, shades and foam height are teaching illustrations. CO₂ total is calculated from measured amounts. Replay repeats the observation of the original inventory, rather than adding more reactants. Other unsupported mixtures remain explicitly unresolved.</p><a href="reaction-effects-reference.txt" target="_blank" rel="noopener">Conditions, limitations & scientific references</a>`;}
function demoRefreshStatus(){const node=document.querySelector('#demoStatus');if(!node)return;const a=selectedEquipment(),out=a?.mixed?demoPredict(a.contents,a):null;node.textContent=out?.demoKind?`${out.demoStage} · ${Math.round((a.demoProgress??1)*100)}% · ${a.demoActive?'running':'paused / complete'}. ${out.note}`:a?.contents?.length?'Selected vessel staged. Press Mix & animate, or use the normal mixing controls.':'Prepare a vessel or select one on the bench.';}
function demoPrepare(){const kind=document.querySelector('#demoPreset').value;addApparatus(kind==='volcano'?'erlenmeyer':'beaker',28+(apparatus.length%3)*22,48);const a=selectedEquipment();const rows=kind==='volcano'?[['Vinegar (ethanoic acid model)','CH₃COOH','acid',.83,30],['Sodium bicarbonate','NaHCO₃','bicarbonate',.8,30],['Dishwashing liquid (neutral model)','Neutral surfactant mixture','detergent',null,1],['Red food colouring','Food dye · visual trace','foodDye',null,.2]]:[[kind==='sucrose'?'Sucrose solution':'Glucose solution',kind==='sucrose'?'C₁₂H₂₂O₁₁':'C₆H₁₂O₆',kind==='sucrose'?'sucrose':'glucose',.05,10],[kind==='hydroxide'?'Sodium hydroxide':'Sodium carbonate',kind==='hydroxide'?'NaOH':'Na₂CO₃',kind==='hydroxide'?'base':'carbonate',kind==='hydroxide'?.33:.1,10],['Potassium permanganate','KMnO₄','permanganate',.001,1]];a.contents=rows.map(([reagent,f,type,molarity,volume])=>({reagent,formula:f+(molarity!=null?' · '+molarity+' M':''),type,molarity,volume,mass:0,color:type==='permanganate'?'#79298e':type==='foodDye'?'#d54351':'#f7faf8'}));a.volume=rows.reduce((s,r)=>s+r[4],0);a.mixed=false;redrawBench();}
document.addEventListener('click',event=>{const action=event.target.closest('[data-demo]')?.dataset.demo;if(!action)return;if(action==='prepare'){demoPrepare();return;}const a=selectedEquipment();if(!a?.contents?.length)return;if(action==='mix'){a.mixed=true;}if(action==='replay'){a.demoProgress=0;a.demoActive=true;}if(action==='pause')a.demoActive=!a.demoActive;redrawBench();});
